D-Profile.css:
body{margin:0;font-family:'Baloo 2',-apple-system,BlinkMacSystemFont,'PingFang SC','Hiragino Sans GB','Microsoft YaHei','HarmonyOS Sans SC','MiSans',system-ui,sans-serif;background:#141312;color:#F2EFEA}
a{color:#FFB27A;text-decoration:none}a:hover{color:#FFC9A3}
button,a{transition:transform .12s ease,box-shadow .15s ease,filter .15s ease,background-color .15s ease}
button:not(:disabled):hover,a:hover{filter:brightness(1.03)}
button:not(:disabled):active,a:active{transform:translateY(1px) scale(.99)}
button:focus-visible,a:focus-visible{outline:3px solid #6C63FF;outline-offset:3px}
.pp-nav:hover{background:#2D2A27}
.pp-set:hover{background:#262421}
h1,h2,h3{line-height:1.25;letter-spacing:-0.01em;text-wrap:balance}p{line-height:1.6}
body{-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;font-variant-numeric:tabular-nums}
.pp-um:hover{background:#262421;filter:none}
/*pp-glassbtn*/a[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:active,button[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:not(:disabled):active{transform:scale(.97)!important;filter:brightness(.95)!important}/*pp-eqcols*/main[style*="1fr) 340px"]{grid-template-rows:auto auto auto 1fr;align-items:stretch}main[style*="1fr) 340px"]>div,main[style*="1fr) 340px"]>aside{display:contents!important}main[style*="1fr) 340px"]>div>:nth-child(1){grid-column:1;grid-row:1}main[style*="1fr) 340px"]>div>:nth-child(2){grid-column:1;grid-row:2}main[style*="1fr) 340px"]>div>:nth-child(3){grid-column:1;grid-row:3}main[style*="1fr) 340px"]>div>:nth-child(4){grid-column:1;grid-row:4}main[style*="1fr) 340px"]>aside>:nth-child(1){grid-column:2;grid-row:1/3}main[style*="1fr) 340px"]>aside>:nth-child(2){grid-column:2;grid-row:3}main[style*="1fr) 340px"]>aside>:nth-child(3){grid-column:2;grid-row:4}/*pp-eqcols-end*/

